const rawText = $input.item.json.text || "";

// Extract metadata fields using Regex
const invoiceNumMatch = rawText.match(/INVOICE NUMBER:\s*([A-Z0-9-]+)/i);
const dateMatch = rawText.match(/DATE:\s*([0-9-]+)/i);
const vendorMatch = rawText.match(/VENDOR:\s*([^\r\n]+)/i);
const totalMatch = rawText.match(/TOTAL:\s*([0-9.]+)/i);
const subtotalMatch = rawText.match(/SUBTOTAL:\s*([0-9.]+)/i);
const taxMatch = rawText.match(/TAX:\s*([0-9.]+)/i);

// Extract line items
const itemRegex = /ITEM:\s*([^x]+)x([0-9]+)\s*@\s*([0-9.]+)\s*USD\s*=\s*([0-9.]+)\s*USD/gi;
const lineItems = [];
let match;
while ((match = itemRegex.exec(rawText)) !== null) {
  lineItems.push({
    sku: "PDF-EXTRACTED-SKU",
    description: match[1].trim(),
    quantity: parseInt(match[2], 10),
    unitPrice: parseFloat(match[3]),
    total: parseFloat(match[4])
  });
}

return {
  json: {
    sourceType: "PDF_INVOICE",
    orderId: invoiceNumMatch ? invoiceNumMatch[1] : "UNKNOWN_INV",
    orderDate: dateMatch ? dateMatch[1] : new Date().toISOString(),
    customer: {
      fullName: vendorMatch ? vendorMatch[1].trim() : "Unknown Vendor",
      email: "billing@acmeindustrial.com",
      phone: "+1-800-555-0199"
    },
    items: lineItems,
    financials: {
      subtotal: subtotalMatch ? parseFloat(subtotalMatch[1]) : 0,
      tax: taxMatch ? parseFloat(taxMatch[1]) : 0,
      total: totalMatch ? parseFloat(totalMatch[1]) : 0
    }
  }
};

return [
  {
    json: {
      orderId: "LEG-8841",
      orderDate: "10/14/2026",
      sourceTimezone: "America/New_York",
      customer: {
        rawName: " jOHn dOE-sMITH ",
        email: "JOHN.DOE@GMAIL.COM ",
        phone: "(555) 019-2834"
      },
      items: [
        { sku: "item-01", description: "Mechanical Keyboard", unitPrice: " $129.99 ", quantity: 2 },
        { sku: "item-02", description: "Wrist Rest", unitPrice: "24.50", quantity: 1 }
      ],
      discountPercent: 10
    }
  },
  {
    json: {
      orderId: "LEG-8842",
      orderDate: "2026-10-15T08:45:00-07:00",
      sourceTimezone: "America/Los_Angeles",
      customer: {
        rawName: "ALICE WONDERLAND",
        email: "alice@adventures.co.uk",
        phone: "+44 20 7946 0919"
      },
      items: [
        { sku: "item-09", description: "UltraWide Monitor 34-inch", unitPrice: "499.00 USD", quantity: 1 },
        { sku: "item-12", description: "Monitor Arm Mount", unitPrice: "$85.00", quantity: 2 }
      ],
      discountPercent: 15
    }
  }
];

const item = $input.item.json;
const rawDate = item.orderDate;
const tz = item.sourceTimezone || 'UTC';
let parsedDate;
if (rawDate.includes('/')) {
  parsedDate = DateTime.fromFormat(rawDate.trim(), 'MM/dd/yyyy', { zone: tz });
} else {
  parsedDate = DateTime.fromISO(rawDate.trim(), { zone: tz });
}
return {
  json: {
    ...item,
    normalizedDateUtc: parsedDate.toUTC().toISO(),
    displayDate: parsedDate.toFormat('yyyy-MM-dd HH:mm:ss')
  }
};

const item = $input.item.json;
const TAX_RATE = 0.085;
const discountPct = Number(item.discountPercent || 0);
const cleanedItems = (item.items || []).map(line => {
  const cleanPrice = Number(String(line.unitPrice).replace(/[^0-9.-]+/g, '')) || 0;
  const qty = Number(line.quantity) || 1;
  return {
    sku: String(line.sku).toUpperCase().trim(),
    description: String(line.description).trim(),
    quantity: qty,
    unitPrice: cleanPrice,
    lineTotal: Number((cleanPrice * qty).toFixed(2))
  };
});
const subtotal = cleanedItems.reduce((acc, curr) => acc + curr.lineTotal, 0);
const discountAmount = Number((subtotal * (discountPct / 100)).toFixed(2));
const taxableAmount = subtotal - discountAmount;
const taxAmount = Number((taxableAmount * TAX_RATE).toFixed(2));
const grandTotal = Number((taxableAmount + taxAmount).toFixed(2));

// Clean customer name
const rawName = (item.customer?.rawName || "").trim();
const cleanedName = rawName.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());

return {
  json: {
    sourceType: "LEGACY_JSON",
    orderId: item.orderId,
    orderDate: item.normalizedDateUtc,
    customer: {
      fullName: cleanedName,
      email: (item.customer?.email || "").toLowerCase().trim(),
      phone: item.customer?.phone || ""
    },
    items: cleanedItems,
    financials: {
      subtotal: Number(subtotal.toFixed(2)),
      discount: discountAmount,
      tax: taxAmount,
      total: grandTotal
    }
  }
};

const items = $input.all();
const totalRevenue = items.reduce((sum, it) => sum + (it.json.amountPayable || 0), 0);

return [{
  json: {
    batchStatus: "COMPLETED",
    totalOrdersProcessed: items.length,
    cumulativeRevenueUSD: Number(totalRevenue.toFixed(2)),
    processedAt: new Date().toISOString()
  }
}];
